#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor batched_bmm_impl_npu(const at::Tensor& A, const at::Tensor& B) {
    TORCH_CHECK(A.dim() >= 2 && B.dim() >= 2, \"Inputs must be at least 2D\");
    TORCH_CHECK(A.size(-1) == B.size(-2), \"Inner dimensions must match for matmul\");

    // Determine output shape
    std::vector<int64_t> output_shape;
    if (A.dim() == 2 && B.dim() == 2) {
        // 2D matmul
        output_shape = {A.size(0), B.size(1)};
        at::Tensor C = at::empty(output_shape, A.options());
        EXEC_NPU_CMD(aclnnBatchedMatrixMultiplicationCustom, A, B, C);
        return C;
    }

    // Handle (batch, M, K) x (batch, K, N)
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3, \"Only 3D batched inputs are supported: (B,M,K) x (B,K,N)\");
    int64_t batch = A.size(0);
    int64_t M = A.size(1);
    int64_t K = A.size(2);
    TORCH_CHECK(B.size(0) == batch && B.size(1) == K, \"Batch and K dimensions must match\");
    int64_t N = B.size(2);
    output_shape = {batch, M, N};

    at::Tensor C = at::empty(output_shape, A.options());

    // Launch per-batch 2D GEMM using the custom kernel
    for (int64_t b = 0; b < batch; ++b) {
        at::Tensor A_b = A[b];
        at::Tensor B_b = B[b];
        at::Tensor C_b = C[b];
        EXEC_NPU_CMD(aclnnBatchedMatrixMultiplicationCustom, A_b, B_b, C_b);
    }
    return C;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("batched_matrix_multiplication_custom", &batched_bmm_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("batched_matrix_multiplication_custom", &batched_bmm_impl_npu, "batched matrix multiplication");
}
